def timed_lru_cache(ttl_seconds=60):
    def decorator(fn):
        cache = {}
        @wraps(fn)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            now = time.time()
            if key in cache and (now - cache[key][1]) < ttl_seconds:
                return cache[key][0]
            res = fn(*args, **kwargs)
            cache[key] = (res, now)
            return res
        return wrapper
    return decorator

